// ---- A braided gravel-bed river, seen from above ---------------------------
// Water parcels run down a wide gravel plain, routed by bed elevation. Each one
// scours where the flow concentrates and dumps its gravel where it slackens, so
// mid-channel BARS build, split the thread around them, and force the flow into
// the anastomosing web that braided rivers actually make. A bar that grows too
// tall pushes its own thread aside — the thread AVULSES, the abandoned one silts
// up, and the braid re-weaves somewhere else.
// Anti-convergence: net aggradation raises the bed forever (balanced by a slow
// base-level fall at the outlet), and stage rises and falls on incommensurate
// cycles — at flood the bars drown and the braid resets, at low stage the
// threads re-incise. The braiding index never settles.
const BW = 184, BH = 104, N = BW * BH;

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function vn(x, y) {
