    for (let s2 = 0; s2 < 260; s2++) {
      const xi = x | 0, yi = y | 0;
      if (xi < 1 || xi >= BW - 1 || yi < 1 || yi >= BH - 1) break;
      const k = yi * BW + xi;
      S.W[k] += 1; S.age[k] = 0;
