const gain = 0.76 + P.energy * 0.46 + K.intensity * 0.14 + A.rms * 0.26;
const laz = K.t * 0.037 + 0.7 + 0.3 * Math.sin(K.t * 0.0163);      // raking light drifts: motion floor on the gravel
