  const i0 = i > 0 ? i - 1 : 0, i1 = i < BW - 1 ? i + 1 : BW - 1;
  const j0 = j > 0 ? j - 1 : 0, j1 = j < BH - 1 ? j + 1 : BH - 1;
  const gx = (S.Z[j * BW + i1] - S.Z[j * BW + i0]) * 30, gy = (S.Z[j1 * BW + i] - S.Z[j0 * BW + i]) * 30;
  const shade = Math.max(0, Math.min(1, 0.5 + (gx * lx + gy * ly) * 0.85));
  const grain = 0.88 + hsh(i * 3, j * 3) * 0.24;
